blocks.text:
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 12px;
}

/* 화면이 넓으면 칸이 늘고, 좁으면 준다. 중단점을 하나도 안 쓴다.
   auto-fill: 빈 칸을 남겨 둔다, auto-fit: 빈 칸을 접어 남은 칸을 늘린다 */

/* 옛 방식. 마지막 것만 빼야 한다 */
.item { margin-right: 8px; }
.item:last-child { margin-right: 0; }

/* 지금. 한 줄 */
.row { display: flex; gap: 8px; }

/* 가로, 세로를 다르게 */
.grid { display: grid; gap: 12px 8px; }   /* 행 사이 12, 열 사이 8 */

// Console 에 붙여넣으면 페이지 폭을 넘는 요소를 찍어 준다
[...document.querySelectorAll('*')]
  .filter((el) => el.getBoundingClientRect().right > document.documentElement.clientWidth + 1)
  .forEach((el) => console.log(Math.round(el.getBoundingClientRect().right), el));

.center   { display: grid; place-items: center; }
.toolbar  { display: flex; align-items: center; gap: 8px; }
.toolbar .right { margin-left: auto; }
.sidebar  { display: grid; grid-template-columns: 200px 1fr; gap: 16px; }
.stack    { display: flex; flex-direction: column; gap: 8px; }
.cards    { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
.page     { display: flex; flex-direction: column; min-height: 100dvh; }
.page main{ flex: 1; }   /* 바닥이 아래로 */

function draw(container: HTMLElement): void {
  // ✗ container.style.display = 'grid';        ← 공용 .tab-panel 과 충돌
  // ✓ 안쪽 wrapper 에 건다
  container.innerHTML = `
    <div class="mywidget-wrap">
      <div class="mywidget-side"></div>
      <div class="mywidget-main"></div>
    </div>`;
}

